//! 📋️ Original DSL arrays receive persistent pages and close every cancelled row frontier.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation,OriginalTurnFailure};
use semio_framework_value::retirement::controlled::ControlledRetirement;
fn fixture()->serde_json::Value{serde_json::from_str(semio_framework_test_fixtures::repo_text!("🧰️framework/🔨️modules/🗣️dsl/🧬️schema/🫴️receiving/📥️owned/📋️persistent/🧪️tests/🧫️fixtures/🔣️.json")).unwrap()}
fn stock()->RetainedCloneGrant{let f=fixture();RetainedCloneGrant{maximum_items:f["maximumItems"].as_u64().unwrap() as usize,maximum_copy_bytes:f["maximumCopyBytes"].as_u64().unwrap() as usize,maximum_capacity_bytes:f["maximumCapacityBytes"].as_u64().unwrap() as usize,maximum_release_bytes:f["maximumReleaseBytes"].as_u64().unwrap() as usize,maximum_depth:f["maximumDepth"].as_u64().unwrap() as usize}}
fn loan()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:4096}}
fn close_value<T:RetireOwned>(caller:&mut OriginalJobFixtureCaller,value:T){let mut value=ControlledRetirement::retain(value);for _ in 0..100_000{if value.terminal_is_empty(){return}caller.turn(loan(),|cx|{let demand=value.selected_demand(loan().maximum_copy_bytes)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|{let result=value.step(grant);RetainedWorkOutcome{result,work:value.last_turn_work()}})?;Ok(())}).unwrap();}panic!("persistent field fixture retirement did not settle")}
fn close(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,cursor:&mut PersistentReceiving<i64>){for _ in 0..100_000{if cursor.terminal_is_empty(){break}caller.turn(loan(),|cx|{let demand=cursor.close_demands(32768)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|{let turn=cursor.close_step(grant);RetainedWorkOutcome{result:turn.result.map(RetainedCloneStep::Progress),work:turn.work}})?;Ok(())}).unwrap();}assert!(cursor.terminal_is_empty());for _ in 0..100_000{if decoder.terminal_is_empty(){return}caller.turn(loan(),|cx|{let demand=decoder.retirement_demands(32768)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|decoder.close_step(grant))?;Ok(())}).unwrap();}panic!("persistent field fixture decoder did not settle")}
fn step(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,cursor:&mut PersistentReceiving<i64>,input:&mut Option<FieldValue>)->Result<(),OriginalTurnFailure>{caller.turn_with_decoder(loan(),decoder,|cx|{let issued=cx.retained_grant();let mut work=0;let result=cx.with_native_receiving::<_,OriginalReceivingPrimary>(|native|{let turn=cursor.step(input,native,32768,issued);work=turn.work;turn.result});let progress=match &result{Ok(progress)=>*progress,Err(error)=>error.retained_progress()};let receipt=cx.consume_receiving_retained(issued,progress);cx.consume_fuel(work);match result{Ok(_)=>{receipt?;Ok(())},Err(primary)=>Err(OriginalTurnFailure{effects:progress,primary:semio_framework_job::OriginalTurnPrimary::Receiving(primary),receipt_refusal:receipt.err(),context_refusal:None})}})}

#[test]
fn persistent_owned_field_matches_serde_sequence_and_original_cancellation(){
    let f=fixture();for row in f["rows"].as_array().unwrap(){let expected:Vec<i64>=serde_json::from_value(row.clone()).unwrap();for cut in std::iter::once(None).chain(f["cancelAfterTurns"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap() as usize))){let mut caller=OriginalJobFixtureCaller::admit(OperationId(997),Generation(17),stock(),||Some(1),u64::MAX,1<<24);let mut decoder=OriginalJobDecodeOwner::empty();let mut input=Some(FieldValue::List(expected.iter().map(|value|FieldValue::Int(*value)).collect()));let mut cursor=PersistentList::<i64>::receiving_cursor();let mut turns=0;while !cursor.is_ready()&&cut.is_none_or(|cut|turns<cut){step(&mut caller,&mut decoder,&mut cursor,&mut input).unwrap();turns+=1;assert!(turns<100_000);}if cut.is_none(){let mut output=None;caller.turn(loan(),|cx|{let turn=cursor.take_into(&mut output,cx.retained_grant());semio_framework_job::receive_original_retained_work(cx,RetainedWorkOutcome{result:turn.result.map(RetainedCloneStep::Progress),work:turn.work})?;Ok(())}).unwrap();let output=output.unwrap();assert_eq!(output.iter().copied().collect::<Vec<_>>(),expected);close_value(&mut caller,output);}else{caller.cancel().cancel_now();}close(&mut caller,&mut decoder,&mut cursor);if let Some(input)=input{close_value(&mut caller,input);}caller.retire(stock());}}
}
